--
-- Table structure for table `forecast_results`
--

DROP TABLE IF EXISTS `forecast_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `forecast_results` (
  `result_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT 0,
  `forecast_date` date NOT NULL,
  `predicted_quantity` decimal(12,2) NOT NULL,
  `confidence_score` decimal(6,4) DEFAULT NULL,
  `model_version` varchar(20) DEFAULT '1.0.0',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `horizon_type` varchar(20) NOT NULL DEFAULT 'daily',
  PRIMARY KEY (`result_id`),
  UNIQUE KEY `unique_forecast_horizon` (`product_id`,`forecast_date`,`horizon_type`),
  KEY `idx_forecast_date` (`forecast_date`)
) ENGINE=InnoDB AUTO_INCREMENT=2614 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
